use anyhow::{Context, Result, ensure};

#[test]
#[ignore = "requires image fixtures generated by the official MiniCPM-o processor outside Git"]
fn official_image_slices_pixels_and_placeholders() -> Result<()> {
    let root = std::path::PathBuf::from(std::env::var("LIA_MINICPMO_IMAGE_ORACLE")?);
    let cases: serde_json::Value =
        serde_json::from_reader(std::fs::File::open(root.join("cases.json"))?)?;
    for case in cases.as_array().context("missing official image cases")? {
        let bytes = std::fs::read(root.join(case["image"].as_str().context("missing image")?))?;
        let maximum = usize::try_from(case["max_slices"].as_u64().context("missing slice limit")?)?;
        let prepared = lia::models::minicpm_o45::prepare(&bytes, maximum)?;
        let dimensions = prepared.plan.slice_dimensions();
        let expected: Vec<[usize; 2]> = case["sizes"]
            .as_array()
            .context("missing sizes")?
            .iter()
            .map(|s| {
                Ok([
                    usize::try_from(s[0].as_u64().context("missing width")?)?,
                    usize::try_from(s[1].as_u64().context("missing height")?)?,
                ])
            })
            .collect::<Result<_>>()?;
        ensure!(
            dimensions == expected,
            "official image slice dimension mismatch"
        );
        ensure!(
            prepared.plan.placeholder(2, true)
                == case["placeholder"]
                    .as_str()
                    .context("missing placeholder")?,
            "official image placeholder mismatch"
        );
        let files = case["pixels"]
            .as_array()
            .context("missing reference pixels")?;
        ensure!(
            files.len() == prepared.slices.len(),
            "image slice count mismatch"
        );
        let mut maximum_error = 0.0f32;
        for (slice, file) in prepared.slices.iter().zip(files) {
            let reference =
                std::fs::read(root.join(file.as_str().context("missing pixel filename")?))?;
            ensure!(
                reference.len() == slice.pixels.len() * 4,
                "reference pixel extent mismatch"
            );
            for (&actual, bytes) in slice.pixels.iter().zip(reference.chunks_exact(4)) {
                let expected = f32::from_le_bytes(bytes.try_into().unwrap());
                maximum_error = maximum_error.max((actual - expected).abs());
            }
        }
        println!(
            "{} slices={maximum}: pixel max_abs={maximum_error}",
            case["image"]
        );
        ensure!(
            maximum_error < 1e-6,
            "official image pixel mismatch: {maximum_error}"
        );
    }
    Ok(())
}
